export const RRB_JE_CBT2_TECHNICAL_CIVIL_1: Question[] = [
  { id: 'rrb-je-c2-civ-001', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The process of hardening and gaining strength of concrete after casting, achieved by keeping it moist to allow proper hydration of cement, is called:', options: ['Curing', 'Compaction', 'Batching', 'Screeding'], correctIndex: 0, explanation: 'Curing is the process of maintaining adequate moisture and temperature in freshly placed concrete to allow proper hydration of cement, ensuring the concrete gains its designed strength.', source },
  { id: 'rrb-je-c2-civ-002', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'Ordinary Portland Cement (OPC) primarily consists of compounds formed from which two main raw materials?', options: ['Sand and gravel', 'Limestone (calcareous material) and clay (argillaceous material)', 'Gypsum and water only', 'Steel slag and fly ash only'], correctIndex: 1, explanation: 'Ordinary Portland Cement is primarily manufactured by heating a mixture of limestone (calcareous material) and clay (argillaceous material) in a kiln to form clinker, which is then ground with a small amount of gypsum.', source },
  { id: 'rrb-je-c2-civ-003', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The setting time of cement during which it should not be disturbed after mixing, known as the "initial setting time" as per IS standards, is intended to give a minimum working time of approximately:', options: ['5 minutes', '30 minutes', '10 hours', '48 hours'], correctIndex: 1, explanation: 'The initial setting time of ordinary Portland cement is specified as a minimum of 30 minutes, giving workers adequate time to place and finish the concrete before it begins to set.', source },
  { id: 'rrb-je-c2-civ-004', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'A brick is generally considered of good quality if, when soaked in water for 24 hours, its water absorption by weight does not exceed approximately:', options: ['5%', '20%', '50%', '75%'], correctIndex: 1, explanation: 'A good quality brick should generally not absorb more than about 20% of its dry weight in water after 24 hours of soaking, as excessive absorption indicates high porosity and reduced durability.', source },
  { id: 'rrb-je-c2-civ-005', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The property of a building material that allows it to be hammered or rolled into thin sheets without cracking is called:', options: ['Ductility', 'Malleability', 'Elasticity', 'Toughness'], correctIndex: 1, explanation: 'Malleability is the property that allows a material to be hammered or rolled into thin sheets without cracking, as distinct from ductility, which refers to being drawn into thin wires.', source },
  { id: 'rrb-je-c2-civ-006', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The property of a material that allows it to be drawn into thin wires under tensile stress without breaking is called:', options: ['Malleability', 'Ductility', 'Brittleness', 'Hardness'], correctIndex: 1, explanation: 'Ductility is the property that allows a material to be drawn into thin wires under tensile stress without breaking, commonly seen in metals such as copper and mild steel.', source },
  { id: 'rrb-je-c2-civ-007', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'Timber that has not been seasoned (dried) properly before use in construction is primarily prone to which defect over time?', options: ['Excessive hardness', 'Warping and shrinkage', 'Increased fire resistance', 'Increased load-bearing capacity'], correctIndex: 1, explanation: 'Unseasoned (improperly dried) timber loses moisture gradually after being put into use, leading to warping, shrinkage, and cracking, which seasoning before use helps to prevent.', source },
  { id: 'rrb-je-c2-civ-008', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The standard water-cement ratio in concrete refers to the ratio, by weight, of:', options: ['Cement to sand', 'Water to cement', 'Coarse aggregate to fine aggregate', 'Cement to coarse aggregate'], correctIndex: 1, explanation: 'The water-cement ratio is the ratio, by weight, of the water used to the cement used in a concrete mix, and it significantly influences the strength and workability of the resulting concrete.', source },
  { id: 'rrb-je-c2-civ-009', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'A mixture of cement, sand, and water (without coarse aggregate), used for plastering walls and jointing masonry, is called:', options: ['Concrete', 'Mortar', 'Grout only', 'Slurry only'], correctIndex: 1, explanation: 'Mortar is a mixture of a binder (typically cement), fine aggregate (sand), and water, without coarse aggregate, used for plastering and jointing masonry units such as bricks and blocks.', source },
  { id: 'rrb-je-c2-civ-010', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The process of removing entrapped air and achieving maximum density in freshly placed concrete, typically done using a vibrator, is called:', options: ['Curing', 'Compaction', 'Bleeding', 'Segregation'], correctIndex: 1, explanation: 'Compaction is the process of removing entrapped air from freshly placed concrete, typically using vibration, to achieve maximum density and strength.', source },
  { id: 'rrb-je-c2-civ-011', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The undesirable separation of coarse aggregate from the concrete mix, often occurring during transport, placement, or excessive vibration, is known as:', options: ['Curing', 'Segregation', 'Hydration', 'Bleeding'], correctIndex: 1, explanation: 'Segregation is the undesirable separation of coarse aggregate from the cement-sand mortar in fresh concrete, typically caused by excessive vibration, mishandling, or a poorly proportioned mix.', source },
  { id: 'rrb-je-c2-civ-012', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The grade of concrete designated "M20" indicates that the concrete has a characteristic compressive strength of:', options: ['20 kg/cm² at 7 days', '20 N/mm² at 28 days', '20 tonnes total load capacity', '20% cement content by volume'], correctIndex: 1, explanation: 'In concrete grade designation (e.g., M20), the "M" stands for "Mix" and the number denotes the characteristic compressive strength in N/mm² (MPa) at 28 days of curing.', source },
  { id: 'rrb-je-c2-civ-013', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'The branch of surveying concerned with determining the elevations (heights) of points relative to a given reference datum is called:', options: ['Plane surveying', 'Levelling', 'Triangulation', 'Chain surveying'], correctIndex: 1, explanation: 'Levelling is the branch of surveying concerned with determining the elevations of points relative to a given reference datum (such as mean sea level), used to establish relative heights across a site.', source },
  { id: 'rrb-je-c2-civ-014', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'A surveying instrument used to measure horizontal and vertical angles precisely, widely used for triangulation and detailed control surveys, is called a:', options: ['Chain', 'Theodolite', 'Plane table', 'Ranging rod'], correctIndex: 1, explanation: 'A theodolite is a precision surveying instrument used to measure horizontal and vertical angles, widely used for triangulation, control surveys, and setting out engineering works.', source },
  { id: 'rrb-je-c2-civ-015', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'In levelling, the term "Bench Mark" refers to a:', options: ['Point of unknown elevation to be determined', 'Fixed point of known/assumed elevation, used as a reference for other level measurements', 'The lowest point on a survey line', 'The instrument station where the level is set up'], correctIndex: 1, explanation: 'A Bench Mark is a fixed point of known (or assumed) elevation, used as a reference from which the elevations of other points are determined during a levelling survey.', source },
  { id: 'rrb-je-c2-civ-016', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'The simplest form of land surveying, suitable for small areas with relatively flat terrain, that uses only a chain (or tape) to measure distances and derive the layout, is called:', options: ['Theodolite surveying', 'Chain surveying', 'Photogrammetric surveying', 'GPS surveying'], correctIndex: 1, explanation: 'Chain surveying is the simplest form of land surveying, using a chain or tape to measure linear distances only, suitable for small, relatively flat, open areas.', source },
  { id: 'rrb-je-c2-civ-017', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'A closed traverse, in surveying, refers to a series of connected survey lines that:', options: ['Never intersect any other lines', 'Start and end at the same point (or at points of known position), forming a closed figure', 'Are always perfectly straight', 'Can only be used for road alignment'], correctIndex: 1, explanation: 'A closed traverse is a series of connected survey lines that starts and ends at the same point (or at points of known position), forming a closed geometric figure that allows internal error checking.', source },
  { id: 'rrb-je-c2-civ-018', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'The instrument used in surveying to measure horizontal distances and set out right angles on the ground, using an optical square or cross principle, is called a:', options: ['Dumpy level', 'Optical square/cross staff', 'Prismatic compass', 'Auto level, and nothing else'], correctIndex: 1, explanation: 'A cross staff (or optical square) is a simple surveying instrument used to set out right angles on the ground, commonly used alongside chain surveying to establish offsets.', source },
  { id: 'rrb-je-c2-civ-019', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'Contour lines on a topographic map represent:', options: ['Lines of equal horizontal distance from a fixed point', 'Lines connecting points of equal elevation above a reference datum', 'Property boundary lines only', 'Roads and railway alignments only'], correctIndex: 1, explanation: 'Contour lines on a topographic map connect points of equal elevation above a chosen reference datum, allowing the representation of terrain relief on a two-dimensional map.', source },
  { id: 'rrb-je-c2-civ-020', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'A surveying instrument that uses a magnetic needle to measure the bearing (direction) of a survey line with respect to magnetic north is called a:', options: ['Dumpy level', 'Prismatic compass', 'Plane table', 'Theodolite, and only a theodolite'], correctIndex: 1, explanation: 'A prismatic compass is a surveying instrument that uses a magnetic needle to measure the bearing of a line with respect to magnetic north, commonly used in compass traversing.', source },
  { id: 'rrb-je-c2-civ-021', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'In levelling, the reading taken on a levelling staff held at a point of unknown elevation, whose height is to be determined, is called a:', options: ['Back sight', 'Fore sight', 'Intermediate sight (or fore sight, generally)', 'Datum sight'], correctIndex: 2, explanation: 'A fore sight (or intermediate sight for a point not marking a change of instrument position) is the staff reading taken at a point of unknown elevation, used to determine that point\'s reduced level relative to the instrument\'s height of collimation.', source },
  { id: 'rrb-je-c2-civ-022', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The bulking of sand refers to the phenomenon in which:', options: ['Dry sand occupies more volume than wet sand of the same weight', 'Damp/moist sand occupies a greater volume than the same weight of dry sand, due to surface moisture films around particles', 'Sand permanently increases in weight when exposed to air', 'Sand particles chemically bond with water'], correctIndex: 1, explanation: 'Bulking of sand refers to the increase in volume of a given weight of sand caused by the film of moisture around each sand particle, which pushes particles apart; this bulking effect is greatest at a certain moisture content and reduces again as the sand becomes fully saturated.', source },
  { id: 'rrb-je-c2-civ-023', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The natural moisture content at which a soil, when disturbed, changes from a plastic state to a liquid state and begins to flow, is called the:', options: ['Plastic limit', 'Liquid limit', 'Shrinkage limit', 'Optimum moisture content'], correctIndex: 1, explanation: 'The liquid limit is the moisture content at which a soil transitions from a plastic state to a liquid state, one of the key Atterberg limits used to classify fine-grained soils.', source },
  { id: 'rrb-je-c2-civ-024', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The moisture content below which a soil changes from a semi-solid state to a plastic state (the minimum moisture at which it can be rolled into threads without crumbling) is called the:', options: ['Liquid limit', 'Plastic limit', 'Shrinkage limit', 'Field capacity'], correctIndex: 1, explanation: 'The plastic limit is the moisture content at which a soil changes from a semi-solid to a plastic state, marking the lower boundary of the plastic range of the soil.', source },
  { id: 'rrb-je-c2-civ-025', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The numerical difference between the liquid limit and the plastic limit of a soil, indicating the range of moisture content over which the soil remains plastic, is called the:', options: ['Shrinkage index', 'Plasticity index', 'Liquidity index', 'Consistency index'], correctIndex: 1, explanation: 'The Plasticity Index (PI) is the numerical difference between the liquid limit and the plastic limit, representing the range of moisture content over which a soil behaves plastically.', source },
  { id: 'rrb-je-c2-civ-026', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The compaction test conducted to determine the optimum moisture content (OMC) and maximum dry density (MDD) of a soil for earthwork purposes is commonly known as the:', options: ['California Bearing Ratio (CBR) test', 'Proctor compaction test', 'Direct shear test', 'Consolidation test'], correctIndex: 1, explanation: 'The Proctor compaction test (standard or modified) is used to determine the optimum moisture content and maximum dry density of a soil, which are used to guide field compaction for earthwork.', source },
  { id: 'rrb-je-c2-civ-027', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The property of a saturated, cohesive soil to gradually decrease in volume over time under a sustained load, as pore water is slowly squeezed out, is called:', options: ['Compaction', 'Consolidation', 'Liquefaction', 'Permeability'], correctIndex: 1, explanation: 'Consolidation is the gradual reduction in volume of a saturated, cohesive (fine-grained) soil under sustained load, as excess pore water pressure dissipates and water is slowly expelled from the soil pores over time.', source },
  { id: 'rrb-je-c2-civ-028', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The ease with which water can flow through the voids of a soil mass is described by its:', options: ['Porosity only', 'Specific gravity', 'Void ratio only', 'Permeability'], correctIndex: 3, explanation: 'Permeability describes the ease with which water can flow through the interconnected voids of a soil mass, and it is a critical property in seepage, drainage, and foundation design.', source },
  { id: 'rrb-je-c2-civ-029', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The ratio of the volume of voids to the volume of solids in a given soil mass is called the:', options: ['Porosity', 'Degree of saturation', 'Void ratio', 'Water content'], correctIndex: 2, explanation: 'The void ratio is defined as the ratio of the volume of voids to the volume of solids in a soil mass, distinct from porosity, which is the ratio of the volume of voids to the total volume of the soil mass.', source },
  { id: 'rrb-je-c2-civ-030', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'A shallow foundation that transfers structural load to soil at a relatively small depth, typically used when the soil near the surface has adequate bearing capacity, is generally called a(n):', options: ['Isolated (spread) footing', 'Pile foundation', 'Caisson foundation', 'Well foundation'], correctIndex: 0, explanation: 'An isolated (spread) footing is a common type of shallow foundation that transfers a column\'s load to the soil at a relatively small depth, used when the near-surface soil has adequate bearing capacity.', source },
  { id: 'rrb-je-c2-civ-031', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'A deep foundation, consisting of a slender structural member driven or bored into the ground, used to transfer structural loads to deeper, stronger soil or rock strata when shallow foundations are inadequate, is called a:', options: ['Raft foundation', 'Strip footing', 'Combined footing', 'Pile foundation'], correctIndex: 3, explanation: 'A pile foundation is a deep foundation consisting of slender structural members driven or bored deep into the ground, transferring structural loads to deeper, stronger strata when the near-surface soil is inadequate.', source },
  { id: 'rrb-je-c2-civ-032', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The maximum load per unit area that a soil can safely support without undergoing excessive settlement or shear failure is called the:', options: ['Ultimate tensile strength', 'Modulus of elasticity of soil', 'Safe bearing capacity of soil', 'Angle of repose'], correctIndex: 2, explanation: 'The safe bearing capacity of soil is the maximum load per unit area that the soil can safely support without excessive settlement or shear failure, forming the basis for foundation design.', source },
  { id: 'rrb-je-c2-civ-033', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The maximum angle, measured from the horizontal, at which a heap of loose granular soil material will stand without slipping or sliding, is called the:', options: ['Angle of repose', 'Angle of internal friction only', 'Angle of shearing resistance only', 'Slope stability angle'], correctIndex: 0, explanation: 'The angle of repose is the maximum angle, measured from the horizontal, at which a heap of loose granular material can stand without slipping, closely related to (but not always identical to) the material\'s angle of internal friction.', source },
  { id: 'rrb-je-c2-civ-034', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'Which classification system, widely adopted for engineering purposes and based on grain size distribution and Atterberg limits, is commonly used to classify soils in India (and internationally)?', options: ['AASHTO Classification only', 'FAO Soil Classification System only', 'Munsell Colour System', 'Unified Soil Classification System (USCS)'], correctIndex: 3, explanation: 'The Unified Soil Classification System (USCS), based on grain size distribution and Atterberg limits (for fine-grained soils), is a widely adopted system for engineering classification of soils.', source },
  { id: 'rrb-je-c2-civ-035', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'The phenomenon in which a saturated, loose, granular soil (such as fine sand) temporarily loses its shear strength and behaves like a liquid, often triggered by sudden shock loads such as an earthquake, is called:', options: ['Consolidation', 'Capillary rise', 'Liquefaction', 'Percolation'], correctIndex: 2, explanation: 'Liquefaction is the phenomenon in which a saturated, loose, granular soil temporarily loses its shear strength and behaves like a liquid, typically triggered by sudden shock loading such as an earthquake.', source },
  { id: 'rrb-je-c2-civ-036', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'A widely used empirical test, expressed as a percentage, used to evaluate the strength of a subgrade soil for the design of flexible pavement thickness, is the:', options: ['California Bearing Ratio (CBR) test', 'Standard Penetration Test (SPT)', 'Vane shear test', 'Sieve analysis'], correctIndex: 0, explanation: 'The California Bearing Ratio (CBR) test is a widely used, standardised test that evaluates the strength of a subgrade soil, expressed as a percentage relative to a standard crushed-stone material, used in flexible pavement thickness design.', source },
  { id: 'rrb-je-c2-civ-037', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: "Bernoulli's theorem, applied to the steady flow of an ideal, incompressible fluid, states that the sum of pressure energy, kinetic energy, and potential energy per unit weight remains:", options: ['Always increasing along the flow', 'Always decreasing along the flow', 'Dependent only on the fluid\'s temperature', 'Constant along a streamline (in the absence of losses)'], correctIndex: 3, explanation: "Bernoulli's theorem states that, for the steady, frictionless flow of an ideal incompressible fluid, the sum of pressure energy, kinetic energy, and potential energy per unit weight remains constant along a streamline.", source },
  { id: 'rrb-je-c2-civ-038', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'The property of a fluid that represents its resistance to gradual deformation or flow, arising from internal friction between adjacent fluid layers moving at different velocities, is called:', options: ['Density', 'Surface tension', 'Viscosity', 'Compressibility'], correctIndex: 2, explanation: "Viscosity is a fluid's resistance to gradual deformation or flow, arising from internal friction between adjacent layers of fluid moving at different velocities relative to each other.", source },
  { id: 'rrb-je-c2-civ-039', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A device installed in a pipeline or open channel to measure the rate of fluid flow, commonly working on the principle of a pressure differential created by a constriction, is called a:', options: ['Venturimeter (or orifice meter)', 'Manometer only', 'Barometer', 'Hydrometer'], correctIndex: 0, explanation: 'A Venturimeter (and similarly, an orifice meter) measures the rate of fluid flow through a pipeline by creating a constriction and measuring the resulting pressure differential, which is related to the flow rate.', source },
  { id: 'rrb-je-c2-civ-040', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A hydraulic structure built across a river or channel to raise the water level and/or divert water for irrigation, without necessarily storing a large volume of water, is called a:', options: ['Dam', 'Aqueduct', 'Syphon', 'Weir/barrage'], correctIndex: 3, explanation: 'A weir (or barrage, for larger structures with gates) is built across a river or channel to raise the water level and divert flow for irrigation or other uses, typically without impounding a large storage volume like a dam does.', source },
  { id: 'rrb-je-c2-civ-041', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'The type of flow in which fluid particles move in smooth, parallel layers with no lateral mixing, typically occurring at low velocities, is called:', options: ['Turbulent flow', 'Uniform flow only', 'Laminar flow', 'Steady flow only'], correctIndex: 2, explanation: 'Laminar flow is characterised by fluid particles moving in smooth, parallel layers with no lateral mixing, typically occurring at relatively low velocities and low Reynolds numbers.', source },
  { id: 'rrb-je-c2-civ-042', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: "The dimensionless number used to determine whether a fluid flow is laminar or turbulent, based on the ratio of inertial forces to viscous forces, is called the:", options: ["Reynolds Number", "Froude Number", "Mach Number", "Weber Number"], correctIndex: 0, explanation: "The Reynolds Number, a dimensionless ratio of inertial forces to viscous forces, is used to predict whether fluid flow will be laminar (low Reynolds Number) or turbulent (high Reynolds Number).", source },
  { id: 'rrb-je-c2-civ-043', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A machine used to lift water from a lower level to a higher level, or to move water/fluid through a piping system, by converting mechanical energy into hydraulic energy, is called a:', options: ['Turbine', 'Compressor only, and nothing else', 'Manometer', 'Pump'], correctIndex: 3, explanation: 'A pump is a machine that converts mechanical energy into hydraulic energy, used to lift water or move fluid through a piping system, as opposed to a turbine, which converts hydraulic energy into mechanical energy.', source },
  { id: 'rrb-je-c2-civ-044', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'The pressure exerted by a fluid at rest, due to the weight of the fluid column above the point of measurement, is called:', options: ['Dynamic pressure', 'Atmospheric pressure only', 'Hydrostatic pressure', 'Vapour pressure'], correctIndex: 2, explanation: 'Hydrostatic pressure is the pressure exerted by a fluid at rest at a given point, due to the weight of the fluid column above it, and it increases linearly with depth.', source },
  { id: 'rrb-je-c2-civ-045', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A U-shaped instrument, containing a liquid such as mercury, used to measure the pressure difference between two points in a fluid system, is called a:', options: ['Manometer', 'Venturimeter', 'Pitot tube', 'Piezometer only'], correctIndex: 0, explanation: 'A manometer is a U-shaped (or similar) instrument containing a liquid, used to measure the pressure or pressure difference between two points in a fluid system, based on the height of the liquid column displaced.', source },
  { id: 'rrb-je-c2-civ-046', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A pipe running full and flowing under pressure (rather than partially full with a free surface) is generally analysed using principles of:', options: ['Open channel flow', 'Groundwater seepage flow only', 'Free surface flow only', 'Pipe flow (closed conduit flow)'], correctIndex: 3, explanation: 'A pipe flowing full under pressure is analysed as pipe flow (closed conduit flow), governed by the pressure gradient, whereas a partially filled pipe or channel with a free surface is analysed as open channel flow, governed by gravity.', source },
  { id: 'rrb-je-c2-civ-047', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'The point of a submerged plane surface at which the total resultant hydrostatic pressure force may be considered to act is called the:', options: ['Centre of gravity', 'Metacentre', 'Centre of pressure', 'Centroid of area only'], correctIndex: 2, explanation: 'The centre of pressure is the point on a submerged plane surface at which the total resultant hydrostatic pressure force may be considered to act, and it generally lies below the centroid of the submerged area.', source },
  { id: 'rrb-je-c2-civ-048', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'The depth of water (usually expressed in mm or cm) required to be supplied to a crop during its entire growth period, to meet evapotranspiration and other losses, is called the:', options: ['Delta of a crop', 'Duty of water', 'Base period', 'Consumptive use only'], correctIndex: 0, explanation: 'The Delta of a crop refers to the total depth of water required by the crop over its entire base period (growth duration) to meet evapotranspiration and other losses.', source },
  { id: 'rrb-je-c2-civ-049', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'In irrigation engineering, "duty" of water refers to the:', options: ['Total volume of water stored in a reservoir', 'The pressure at which water is delivered to fields', 'The number of canals in an irrigation network', 'Area of land that can be irrigated using a unit volume (or unit discharge) of water over the crop\'s base period'], correctIndex: 3, explanation: 'The "duty" of water is the area of land that can be irrigated by a unit volume (or unit discharge) of water applied over the crop\'s entire base period, and it is inversely related to the "delta" of the crop.', source },
  { id: 'rrb-je-c2-civ-050', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'An irrigation method in which water is applied to crops through a network of small-diameter pipes and emitters, delivering water directly and slowly to the root zone, is called:', options: ['Flood irrigation', 'Furrow irrigation only', 'Drip irrigation', 'Basin irrigation'], correctIndex: 2, explanation: 'Drip irrigation applies water directly to the crop root zone slowly, through a network of pipes and emitters, minimising water loss due to evaporation and runoff compared to flood or furrow methods.', source },
  { id: 'rrb-je-c2-civ-051', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'A canal that carries water from the river headworks and is the main source of supply for the entire canal irrigation system, from which all branch and distributary canals take off, is called the:', options: ['Main canal', 'Distributary canal', 'Field channel', 'Escape channel'], correctIndex: 0, explanation: 'The main canal is the primary canal that carries water directly from the river headworks, from which branch canals and distributaries further take off to serve the irrigation network.', source },
  { id: 'rrb-je-c2-civ-052', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'A hydraulic structure constructed at the point where an irrigation canal crosses a natural drainage (such as a stream), carrying the canal water over the drainage in a trough, is called a(n):', options: ['Cross regulator', 'Canal fall', 'Escape', 'Aqueduct'], correctIndex: 3, explanation: 'An aqueduct is a hydraulic cross-drainage structure that carries irrigation canal water over a natural drainage (like a stream) in an elevated trough, when the drainage bed level is below the canal bed level.', source },
  { id: 'rrb-je-c2-civ-053', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A structural member that is subjected primarily to transverse loads and resists them mainly by bending, typically supported at its ends, is called a:', options: ['Column', 'Strut', 'Beam', 'Tie'], correctIndex: 2, explanation: 'A beam is a structural member subjected primarily to transverse (perpendicular) loads, resisting them mainly through bending action, and is typically supported at its ends or at other points along its length.', source },
  { id: 'rrb-je-c2-civ-054', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A vertical structural member designed primarily to carry axial compressive loads from beams and slabs above, transferring them down to the foundation, is called a:', options: ['Column', 'Beam', 'Truss', 'Purlin'], correctIndex: 0, explanation: 'A column is a vertical structural member designed primarily to carry axial compressive loads, transferring loads from beams and slabs above down to the foundation.', source },
  { id: 'rrb-je-c2-civ-055', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A support condition that resists both vertical and horizontal forces, as well as bending moment (allowing no rotation or translation at the support), is called a:', options: ['Roller support', 'Hinged (pinned) support', 'Simple support only', 'Fixed support'], correctIndex: 3, explanation: 'A fixed support resists vertical force, horizontal force, and bending moment simultaneously, allowing no translation or rotation at the support, unlike a hinged support (which resists translation but allows rotation) or a roller support (which resists only perpendicular force).', source },
  { id: 'rrb-je-c2-civ-056', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A support that allows rotation but resists both horizontal and vertical translation of the structural member at that point is called a:', options: ['Roller support', 'Fixed support', 'Hinged (pinned) support', 'Free end'], correctIndex: 2, explanation: 'A hinged (pinned) support resists both horizontal and vertical translation at that point while allowing free rotation, as distinct from a fixed support (which also resists rotation) and a roller support (which resists only one direction of force).', source },
  { id: 'rrb-je-c2-civ-057', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A beam that is fixed (built-in) at one end and completely free at the other end, with no support at the free end, is called a:', options: ['Cantilever beam', 'Simply supported beam', 'Continuous beam', 'Fixed beam'], correctIndex: 0, explanation: 'A cantilever beam is fixed (built-in) at one end and entirely free at the other, resisting the applied loads through bending and shear developed at the fixed end.', source },
  { id: 'rrb-je-c2-civ-058', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The point along a beam\'s length at which the bending moment changes sign (from sagging to hogging, or vice versa) is called the:', options: ['Neutral axis', 'Centroid', 'Shear centre', 'Point of contraflexure (inflection point)'], correctIndex: 3, explanation: 'The point of contraflexure (or inflection point) is the location along a beam where the bending moment changes sign from positive (sagging) to negative (hogging), and the bending moment at this point is zero.', source },
  { id: 'rrb-je-c2-civ-059', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: "In the theory of bending, the imaginary layer within a beam's cross-section that experiences neither tension nor compression (zero longitudinal stress) during bending is called the:", options: ['Extreme fibre', 'Centre of pressure', 'Neutral axis', 'Shear plane'], correctIndex: 2, explanation: "The neutral axis is the imaginary layer within a beam's cross-section that experiences zero longitudinal (bending) stress, with fibres above and below it experiencing compression and tension respectively (or vice versa, depending on the direction of bending).", source },
  { id: 'rrb-je-c2-civ-060', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A framed structure composed of straight members connected at their ends by pin joints, designed such that all members carry only axial (tension or compression) forces and no bending, is called a:', options: ['Truss', 'Frame (rigid-jointed structure)', 'Continuous beam', 'Arch, and only an arch'], correctIndex: 0, explanation: 'A truss is a framed structure of straight members connected at pin joints, designed so that all members ideally carry only axial forces (tension or compression), with no bending moment, under the assumption of loads applied only at the joints.', source },
  { id: 'rrb-je-c2-civ-061', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: "The property of a beam's cross-section that measures its resistance to bending, dependent on the shape and distribution of area relative to the neutral axis, is called the:", options: ['Modulus of elasticity', 'Poisson\'s ratio', 'Modulus of rigidity', 'Moment of inertia'], correctIndex: 3, explanation: "The moment of inertia (second moment of area) of a beam's cross-section measures its resistance to bending, and depends on the shape and distribution of the cross-sectional area relative to the neutral axis.", source },
  { id: 'rrb-je-c2-civ-062', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: "According to Hooke's Law, within the elastic limit of a material, stress is:", options: ['Inversely proportional to strain', 'Independent of strain', 'Directly proportional to strain', 'Proportional to the square of strain'], correctIndex: 2, explanation: "Hooke's Law states that, within the elastic limit of a material, stress is directly proportional to strain, with the constant of proportionality being the material's modulus of elasticity (Young's modulus).", source },
  { id: 'rrb-je-c2-civ-063', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The ratio of lateral (transverse) strain to longitudinal (axial) strain, within the elastic limit, for a material under axial loading is called:', options: ["Poisson's ratio", "Young's modulus", 'Bulk modulus', 'Modulus of rigidity'], correctIndex: 0, explanation: "Poisson's ratio is the ratio of lateral strain to longitudinal strain within the elastic limit, when a material is subjected to axial loading.", source },
  { id: 'rrb-je-c2-civ-064', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'Steel reinforcement bars are embedded in concrete beams and slabs primarily because concrete is strong in compression but relatively weak in:', options: ['Compression as well', 'Shear only, but not tension', 'Density', 'Tension'], correctIndex: 3, explanation: 'Concrete is strong in compression but relatively weak in tension; steel reinforcement bars, which are strong in tension, are embedded to resist the tensile stresses that develop in reinforced concrete members.', source },
  { id: 'rrb-je-c2-civ-065', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The minimum thickness of concrete cover provided over reinforcement steel in RCC members primarily serves to:', options: ['Increase the total dead load of the structure', 'Reduce the strength of the member deliberately', 'Protect the reinforcement from corrosion and provide fire resistance', 'Serve no functional purpose, only an aesthetic one'], correctIndex: 2, explanation: 'The concrete cover over reinforcement in RCC members primarily protects the steel from corrosion (by keeping out moisture and air) and provides fire resistance, in addition to ensuring adequate bond between steel and concrete.', source },
  { id: 'rrb-je-c2-civ-066', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'In reinforced concrete design, a beam in which the area of tension steel provided is exactly equal to the amount required for both concrete and steel to reach their permissible/limiting stresses simultaneously is called a(n):', options: ['Balanced (economic) section', 'Under-reinforced beam', 'Over-reinforced beam', 'Doubly reinforced beam, and only a doubly reinforced beam'], correctIndex: 0, explanation: 'A balanced (or "economic") section is one in which the tension steel and concrete reach their respective permissible or limiting stresses simultaneously, representing the theoretical dividing line between under-reinforced and over-reinforced sections.', source },
  { id: 'rrb-je-c2-civ-067', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'In building construction estimation, the method of preparing a detailed estimate by calculating the quantities of each item of work (excavation, concreting, masonry, etc.) separately is called the:', options: ['Plinth area method', 'Cube rate method only', 'Approximate estimate method', 'Detailed (item-wise) estimate method'], correctIndex: 3, explanation: 'A detailed (item-wise) estimate is prepared by calculating the quantities of each individual item of work separately (such as excavation, concreting, and masonry) and then applying the corresponding rates to determine costs.', source },
  { id: 'rrb-je-c2-civ-068', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'A rough, quick method of estimating the approximate cost of a building based on its covered (plinth) area multiplied by a predetermined rate per unit area is called the:', options: ['Detailed estimate method', 'Cubic content method only, exclusively', 'Plinth area (superficial area) method', 'Bill of quantities method'], correctIndex: 2, explanation: 'The plinth area method is a quick, approximate method of estimating building cost, calculated by multiplying the covered (plinth) area of the building by a predetermined rate per unit area, based on similar existing buildings.', source },
  { id: 'rrb-je-c2-civ-069', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'A document that itemises, in detail, the quantities and descriptions of all materials and labour required for a construction project, used by contractors to quote a lump-sum or rate-based price, is called a:', options: ['Bill of Quantities (BOQ)', 'Site order book', 'Muster roll only', 'Log book'], correctIndex: 0, explanation: 'A Bill of Quantities (BOQ) is a document that itemises, in detail, the quantities and descriptions of all materials, labour, and works required for a construction project, forming the basis for contractor pricing.', source },
  { id: 'rrb-je-c2-civ-070', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'The written record maintained on a construction site to record the daily attendance and wages of workers is called the:', options: ['Muster roll', 'Bill of Quantities', 'Measurement book', 'Log book only'], correctIndex: 0, explanation: 'A muster roll is a record maintained at a construction site to log the daily attendance and wages payable to workers, particularly for daily-wage/casual labour.', source },
  { id: 'rrb-je-c2-civ-071', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'The government/departmental register in which the detailed measurements of work executed on a construction site are recorded, used as the basis for payment to contractors, is called the:', options: ['Muster roll', 'Cash book only', 'Stock register', 'Measurement Book (MB)'], correctIndex: 3, explanation: 'The Measurement Book (MB) is the official register in which the detailed measurements of work actually executed on site are recorded, forming the basis for verifying and processing contractor payments.', source },
  { id: 'rrb-je-c2-civ-072', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'The amount of money deducted from a contractor\'s running (interim) bills, and retained by the client until satisfactory completion of the defects liability period, is called:', options: ['Earnest money', 'Security deposit only, in every case', 'Retention money', 'Mobilisation advance'], correctIndex: 2, explanation: 'Retention money is the amount deducted from a contractor\'s interim bills and retained by the client until the defects liability period is satisfactorily completed, serving as security against defective work.', source },
  { id: 'rrb-je-c2-civ-073', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'The sum of money that a contractor deposits with the client before the award of a contract, as a guarantee of their seriousness to undertake the work if selected, is called:', options: ['Earnest Money Deposit (EMD)', 'Retention money', 'Performance guarantee only', 'Mobilisation advance'], correctIndex: 0, explanation: 'The Earnest Money Deposit (EMD) is a sum deposited by a bidder/contractor before the award of a contract, as a guarantee of their seriousness and financial capability, and is typically forfeited if the bidder withdraws after winning the tender.', source },
  { id: 'rrb-je-c2-civ-074', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The layer of a flexible pavement road structure that lies directly beneath the wearing (surface) course and primarily distributes the traffic load to the layers below is called the:', options: ['Subgrade', 'Sub-base course only', 'Shoulder', 'Base course'], correctIndex: 3, explanation: 'The base course of a flexible pavement lies directly beneath the wearing (surface) course and primarily helps distribute the traffic load to the sub-base and subgrade layers below.', source },
  { id: 'rrb-je-c2-civ-075', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The natural or compacted soil layer on which the entire pavement structure (sub-base, base, and surface courses) of a road is constructed is called the:', options: ['Shoulder', 'Kerb', 'Subgrade', 'Camber'], correctIndex: 2, explanation: 'The subgrade is the natural or compacted soil layer that forms the foundation on which the entire pavement structure (sub-base, base, and surface courses) of a road is constructed.', source },
  { id: 'rrb-je-c2-civ-076', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The slight, transverse slope provided to a road surface from its centre line towards both edges, primarily to facilitate the drainage of rainwater, is called:', options: ['Camber', 'Gradient', 'Superelevation', 'Sight distance'], correctIndex: 0, explanation: 'Camber is the slight transverse slope given to a road surface from its centre line toward the edges, primarily to allow rainwater to drain off the pavement quickly.', source },
  { id: 'rrb-je-c2-civ-077', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'On a curved section of a road, the transverse slope provided by raising the outer edge relative to the inner edge, in order to counteract the centrifugal force acting on a moving vehicle, is called:', options: ['Camber', 'Gradient', 'Extra widening only', 'Superelevation'], correctIndex: 3, explanation: 'Superelevation (or "banking") is the transverse slope provided on a curved road section, raising the outer edge relative to the inner edge, to counteract the centrifugal force on a vehicle moving along the curve.', source },
  { id: 'rrb-je-c2-civ-078', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The type of stress developed in a structural member when two equal and opposite forces act tangentially across a cross-section, tending to slide one part of the material over the adjacent part, is called:', options: ['Tensile stress', 'Compressive stress', 'Shear stress', 'Bearing stress only'], correctIndex: 2, explanation: 'Shear stress is developed when two equal and opposite forces act tangentially across a cross-section, tending to slide one part of the material over the adjacent part.', source },
  { id: 'rrb-je-c2-civ-079', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The internal resisting force per unit area developed within a material when it is subjected to an external load is generally called:', options: ['Stress', 'Strain', 'Elasticity', 'Deformation only'], correctIndex: 0, explanation: 'Stress is the internal resisting force developed per unit cross-sectional area within a material when it is subjected to an external load.', source },
  { id: 'rrb-je-c2-civ-080', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The ratio of the change in dimension (deformation) of a material to its original dimension, when subjected to a load, is called:', options: ['Stress', 'Modulus of elasticity', 'Resilience only', 'Strain'], correctIndex: 3, explanation: 'Strain is defined as the ratio of the change in dimension (deformation) of a material to its original dimension, when the material is subjected to a load.', source },
  { id: 'rrb-je-c2-civ-081', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'A construction technique in which precast reinforced concrete elements (beams, slabs, or wall panels), manufactured separately, are transported to the site and assembled/erected in position, is called:', options: ['Cast-in-situ construction', 'Prestressed construction only, exclusively', 'Precast construction', 'Composite construction'], correctIndex: 2, explanation: 'Precast construction involves manufacturing reinforced concrete elements separately (often in a factory or casting yard), then transporting and assembling/erecting them in position at the final site.', source },
  { id: 'rrb-je-c2-civ-082', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'Concrete in which internal stresses are intentionally introduced (typically by tensioning high-strength steel tendons) before or during construction, to improve its resistance to service loads, is called:', options: ['Prestressed concrete', 'Reinforced concrete only', 'Fibre-reinforced concrete only', 'Lightweight concrete'], correctIndex: 0, explanation: 'Prestressed concrete has internal compressive stresses intentionally introduced, typically by tensioning high-strength steel tendons before or after casting, to counteract tensile stresses that would otherwise develop under service loads.', source },
  { id: 'rrb-je-c2-civ-083', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: 'A field test conducted by driving a standard split-spoon sampler into soil using repeated blows of a standard hammer, used to estimate the relative density/consistency and bearing capacity of soil in-situ, is called the:', options: ['Proctor compaction test', 'Consolidation test', 'Direct shear test only', 'Standard Penetration Test (SPT)'], correctIndex: 3, explanation: 'The Standard Penetration Test (SPT) is a field test in which a standard split-spoon sampler is driven into soil using repeated blows of a standard hammer, and the number of blows required (N-value) is used to estimate soil density/consistency and approximate bearing capacity.', source },
  { id: 'rrb-je-c2-civ-084', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'A modern surveying/positioning technology that uses signals from a constellation of orbiting satellites to determine the precise geographic location (latitude, longitude, and elevation) of a point on Earth is known as:', options: ['Total station only, without satellites', 'Aerial photography only', 'Global Positioning System (GPS)', 'Tacheometry'], correctIndex: 2, explanation: 'The Global Positioning System (GPS) uses signals from a constellation of orbiting satellites to determine the precise geographic location — latitude, longitude, and elevation — of a receiver on or near the Earth\'s surface.', source },
  { id: 'rrb-je-c2-civ-085', section: 'Technical Abilities', topic: 'Surveying', difficulty: 'medium', question: 'A modern electronic surveying instrument that combines an electronic theodolite (for angle measurement) with an Electronic Distance Measurement (EDM) device (for distance measurement) into a single unit is called a:', options: ['Total station', 'Dumpy level', 'Prismatic compass', 'Plane table, and only a plane table'], correctIndex: 0, explanation: 'A total station is a modern electronic surveying instrument that combines an electronic theodolite with an EDM device, allowing simultaneous measurement of horizontal/vertical angles and distances from a single setup.', source },
  { id: 'rrb-je-c2-civ-086', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'A hydraulic structure used to store a large volume of water by obstructing the flow of a river or stream, primarily for purposes such as irrigation, water supply, flood control, and hydropower generation, is called a:', options: ['Weir', 'Barrage only, exclusively', 'Aqueduct', 'Dam'], correctIndex: 3, explanation: 'A dam is a hydraulic structure built across a river or stream to store a large volume of water, serving purposes such as irrigation, water supply, flood control, and hydropower generation.', source },
  { id: 'rrb-je-c2-civ-087', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'Steel that has been strengthened through a cold-working process (twisting), commonly used as reinforcement bars in RCC construction and identified by a ridged surface pattern, is generally known as:', options: ['Mild steel bars only', 'Cast iron bars', 'Thermo-Mechanically Treated (TMT) bars', 'Wrought iron bars, and nothing else'], correctIndex: 2, explanation: 'Thermo-Mechanically Treated (TMT) bars are steel reinforcement bars produced through a controlled quenching and self-tempering process (a form of heat treatment, distinct from simple cold-twisting), giving them a hard outer surface and a ductile core, and are widely used as reinforcement in modern RCC construction.', source },
  { id: 'rrb-je-c2-civ-088', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A beam supported at both ends, with one end resting on a hinged (pinned) support and the other on a roller support, such that it is free to rotate at both supports, is called a:', options: ['Simply supported beam', 'Cantilever beam', 'Fixed beam', 'Continuous beam only'], correctIndex: 0, explanation: 'A simply supported beam rests on a hinged support at one end and a roller support at the other, free to rotate at both supports, and is one of the most common beam types analysed in structural engineering.', source },
  { id: 'rrb-je-c2-civ-089', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A beam that is continuously supported over more than two supports (i.e., has one or more intermediate supports in addition to its end supports) is called a:', options: ['Simply supported beam', 'Cantilever beam only', 'Overhanging beam', 'Continuous beam'], correctIndex: 3, explanation: 'A continuous beam is supported over more than two supports (with at least one intermediate support), making it statically indeterminate and requiring more advanced analysis than a simply supported beam.', source },
  { id: 'rrb-je-c2-civ-090', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'A test conducted to determine the fineness of cement, by passing a specified weight of cement through a standard sieve and measuring the residue, checks the cement\'s:', options: ['Setting time', 'Soundness', 'Fineness', 'Consistency, and only its consistency'], correctIndex: 2, explanation: 'The fineness test of cement determines the extent to which cement particles have been ground, by passing a specified weight through a standard sieve (typically 90-micron) and measuring the percentage residue.', source },
  { id: 'rrb-je-c2-civ-091', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: "A cement test that checks for the presence of excess free lime or magnesia, which could cause the cement to expand and crack after hardening, is called the:", options: ['Soundness test', 'Fineness test', 'Setting time test only', 'Compressive strength test'], correctIndex: 0, explanation: "The soundness test of cement checks for the presence of excess free lime or magnesia, which, if present in excess, could cause the hardened cement paste to expand unsoundly and crack over time.", source },
  { id: 'rrb-je-c2-civ-092', section: 'Technical Abilities', topic: 'Estimating and Costing', difficulty: 'medium', question: 'The process of preparing an approximate estimate for a proposed engineering project quickly, using broad unit-cost data (such as cost per km of road or cost per bed of a hospital), without detailed item-wise quantities, is generally called a(n):', options: ['Detailed estimate', 'Revised estimate only', 'Supplementary estimate', 'Approximate (preliminary) estimate'], correctIndex: 3, explanation: 'An approximate (preliminary) estimate is prepared quickly using broad unit-cost data, without detailed item-wise quantity calculations, and is typically used at the early planning stage of a project to gauge feasibility.', source },
  { id: 'rrb-je-c2-civ-093', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The maximum size of aggregate that will completely pass through a specified sieve size, used to characterise coarse aggregate for concrete mix design, is called the:', options: ['Fineness modulus', 'Specific gravity of aggregate', 'Nominal maximum size of aggregate', 'Bulk density only'], correctIndex: 2, explanation: 'The nominal maximum size of aggregate refers to the sieve size through which the maximum size of aggregate is specified to completely (or almost completely) pass, and it is a key parameter in concrete mix design.', source },
  { id: 'rrb-je-c2-civ-094', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'A curved structural member that primarily transmits vertical loads to its supports mainly through axial compression, rather than bending, and is commonly used to span openings such as doorways and bridges, is called a(n):', options: ['Arch', 'Truss', 'Cantilever only', 'Portal frame, and nothing else'], correctIndex: 0, explanation: 'An arch is a curved structural member that transmits the loads applied to it primarily to its supports through axial compression along its curved profile, rather than through bending, commonly used to span openings such as doorways and bridges.', source },
  { id: 'rrb-je-c2-civ-095', section: 'Technical Abilities', topic: 'Soil Mechanics', difficulty: 'medium', question: "A retaining structure built to hold back soil (or other material) at a slope steeper than it would naturally assume, and to resist the lateral earth pressure exerted by the retained soil, is called a:", options: ['Retaining wall', 'Bearing wall only', 'Cavity wall', 'Curtain wall'], correctIndex: 0, explanation: 'A retaining wall is a structure built to hold back soil or other material at a slope steeper than its natural angle of repose, resisting the lateral earth pressure exerted by the retained material.', source },
  { id: 'rrb-je-c2-civ-096', section: 'Technical Abilities', topic: 'Hydraulics and Fluid Mechanics', difficulty: 'medium', question: 'The rise of a liquid in a narrow tube (or through the fine pores of a material) above the level of the surrounding liquid, caused by surface tension and adhesive forces, is called:', options: ['Buoyancy', 'Cavitation', 'Percolation only', 'Capillarity (capillary rise)'], correctIndex: 3, explanation: 'Capillarity (capillary rise) is the rise of a liquid in a narrow tube, or through the fine pores of a material, above the level of the surrounding liquid surface, caused by surface tension and adhesive forces between the liquid and the tube/material.', source },
  { id: 'rrb-je-c2-civ-097', section: 'Technical Abilities', topic: 'Irrigation Engineering', difficulty: 'medium', question: 'A method of irrigation in which the entire field is divided into small compartments (basins), each of which is filled with water to a required depth and allowed to stand, commonly used for crops such as rice, is called:', options: ['Sprinkler irrigation', 'Drip irrigation only', 'Basin (check basin) irrigation', 'Sub-surface irrigation'], correctIndex: 2, explanation: 'Basin (check basin) irrigation divides a field into small level compartments, each flooded with water to a required depth and allowed to stand or infiltrate, and is commonly used for crops such as paddy (rice) and orchards.', source },
  { id: 'rrb-je-c2-civ-098', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'The layer of protective, decorative material (typically a cement-sand mix) applied to the exposed surfaces of walls and ceilings to give a smooth, even finish is called:', options: ['Pointing', 'Damp-proofing only', 'Flooring', 'Plastering'], correctIndex: 3, explanation: 'Plastering is the application of a protective, decorative layer (typically a cement-sand or lime-sand mix) to the exposed surfaces of walls and ceilings, giving them a smooth, even finish.', source },
  { id: 'rrb-je-c2-civ-099', section: 'Technical Abilities', topic: 'Building Materials', difficulty: 'medium', question: 'A construction technique providing a barrier (such as a layer of impermeable material) in a building\'s walls or floor to prevent ground moisture from rising into the structure is generally known as:', options: ['Waterproofing (roof treatment) only', 'Termite-proofing only', 'Damp-proofing', 'Fireproofing'], correctIndex: 2, explanation: 'Damp-proofing involves providing a barrier (such as a Damp-Proof Course, made of an impermeable material) in a building\'s walls or floor to prevent ground moisture from rising into the structure by capillary action.', source },
  { id: 'rrb-je-c2-civ-100', section: 'Technical Abilities', topic: 'Structural Analysis', difficulty: 'medium', question: 'The maximum stress that a material can withstand while being stretched or pulled before breaking (failing) is called its:', options: ['Yield strength only', 'Elastic limit only', 'Proportional limit', 'Ultimate tensile strength'], correctIndex: 3, explanation: 'Ultimate tensile strength is the maximum stress that a material can withstand while being stretched or pulled before it breaks or fails, marking the peak point on the material\'s stress-strain curve.', source },
];
